(5905188, 860340, 82999, '<td valign="top">My personal favorite so far.</td>', 'My personal favorite so far.', '2010-03-15 09:32:57.000000', NULL, 1),
(5905214, 859880, 82999, '<td valign="top">Seems more about the bird than the branch to me.  While well executed just didn''t seem to fit the theme to me.</td>', 'Seems more about the bird than the branch to me.  While well executed just didn''t seem to fit the theme to me.', '2010-03-15 09:40:23.000000', NULL, 1),
