(5906891, 859380, 49359, '<td valign="top">I don''t know whether you''ve used topaz or something else but your model doesn''t seem to have any shadows left! It kind of looks like she''s been pasted into the picture... Not really seeing the branch reference either.</td>', 'I don''t know whether you''ve used topaz or something else but your model doesn''t seem to have any shadows left! It kind of looks like she''s been pasted into the picture... Not really seeing the branch reference either.', '2010-03-16 16:47:05.000000', NULL, 1),
(5906892, 859990, 29904, '<td valign="top">Love this!  only criticism - seems a bit over saturated and white blown out. 8</td>', 'Love this!  only criticism - seems a bit over saturated and white blown out. 8', '2010-03-16 16:48:30.000000', NULL, 1),
