(5907120, 860819, 10785, '<td valign="top">I like the reflections shown. It has added interest for that. I think the greyscale is pretty flat. It''s not quite black and white, not quite sepia... just somewhat of a grey tone with no real depth. I think the depth issue is from shooting a flat surface pretty much straight on.</td>', 'I like the reflections shown. It has added interest for that. I think the greyscale is pretty flat. It''s not quite black and white, not quite sepia... just somewhat of a grey tone with no real depth. I think the depth issue is from shooting a flat surface pretty much straight on.', '2010-03-16 21:05:48.000000', NULL, 1),
(5907124, 860115, 10785, '<td valign="top">A good find, however I think this is somewhat out of focus. Also rather than shooting straight on, a different perspective might have helped to add interest by showing the depth of the carving in shadow.</td>', 'A good find, however I think this is somewhat out of focus. Also rather than shooting straight on, a different perspective might have helped to add interest by showing the depth of the carving in shadow.', '2010-03-16 21:07:19.000000', NULL, 1),
(5907125, 860783, 10785, '<td valign="top">I get the fit to the challenge here and it is very unique and creative. I do think the scene is very plain and ordinary, something seen all the time. What could have possibly jazzed this up is showing the pop of red from the box.</td>', 'I get the fit to the challenge here and it is very unique and creative. I do think the scene is very plain and ordinary, something seen all the time. What could have possibly jazzed this up is showing the pop of red from the box.', '2010-03-16 21:09:09.000000', NULL, 1),
(5907136, 860264, 10785, '<td valign="top">This is a good concept. I think the color of the tracks stands out well from the color of the background. One thing about this that could be presented better is the shape.</td>', 'This is a good concept. I think the color of the tracks stands out well from the color of the background. One thing about this that could be presented better is the shape.', '2010-03-16 21:18:51.000000', NULL, 1),
(5907139, 860713, 57447, '<td valign="top">You really captured some nice light with this entry.</td>', 'You really captured some nice light with this entry.', '2010-03-16 21:20:49.000000', NULL, 1),
(5907143, 860749, 57447, '<td valign="top">This is one of the more appealing images to me in this challenge.</td>', 'This is one of the more appealing images to me in this challenge.', '2010-03-16 21:22:39.000000', NULL, 1),
(5907145, 860780, 57447, '<td valign="top">I like the nice tender bud on your branch.</td>', 'I like the nice tender bud on your branch.', '2010-03-16 21:23:40.000000', NULL, 1),
(5907149, 859880, 93283, '<td valign="top">This is a pretty good photo, nice and sharp, with good colors and contrast. You may have a problem with the literal voters, but for voters like me, its a great shot</td>', 'This is a pretty good photo, nice and sharp, with good colors and contrast. You may have a problem with the literal voters, but for voters like me, its a great shot', '2010-03-16 21:28:04.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5907158, 860524, 93283, '<td valign="top">First, the good, The shot definitely meets the challenge topic and the title is clever... The bad, Honestly, for me,  the sculpture in the background really throws off the composition... Also the way the road winds around, it feels as though the frame is tilted. Just my two cents though 5</td>', 'First, the good, The shot definitely meets the challenge topic and the title is clever... The bad, Honestly, for me,  the sculpture in the background really throws off the composition... Also the way the road winds around, it feels as though the frame is tilted. Just my two cents though 5', '2010-03-16 21:31:23.000000', NULL, 1),
(5907161, 859704, 93283, '<td valign="top">After viewing this for a third time, I really like the Chop Suey look of branches just kind of everywhere with a good contrast of black and white... Well done, bumping from 5 to 7</td>', 'After viewing this for a third time, I really like the Chop Suey look of branches just kind of everywhere with a good contrast of black and white... Well done, bumping from 5 to 7', '2010-03-16 21:32:14.000000', NULL, 1),
(5907168, 860324, 93283, '<td valign="top">The good... this shot is really kinda out there, and I love that. It has a really funky vibe with the wire fence, the bright color, and a skunk... The bad, I''m not sure many voters will connect it to the challenge. I mean, you have branches in the photo, so its good enough for me :) but many voters appear to be voting literally... Also, the photo is alittle busy for my personal taste... 5</td>', 'The good... this shot is really kinda out there, and I love that. It has a really funky vibe with the wire fence, the bright color, and a skunk... The bad, I''m not sure many voters will connect it to the challenge. I mean, you have branches in the photo, so its good enough for me :) but many voters appear to be voting literally... Also, the photo is alittle busy for my personal taste... 5', '2010-03-16 21:35:44.000000', NULL, 1),
(5907170, 860521, 93283, '<td valign="top">Nice Hooters... No, really, nice ones... I can never get anywhere near these things without them spooking... Props for the patience. Also, you connected this to the challenge nicely... Well done 6</td>', 'Nice Hooters... No, really, nice ones... I can never get anywhere near these things without them spooking... Props for the patience. Also, you connected this to the challenge nicely... Well done 6', '2010-03-16 21:37:01.000000', NULL, 1),
(5907177, 860282, 93283, '<td valign="top">This shot is kinda out of the box for this challenge, so you may get dinged by the literal voters. I think you connected it well to the challenge, but I think the photo falls alittle short because the screen is too dim... Obviously this is a difficult shot to pull off, but the screen is just too difficult to see. 5</td>', 'This shot is kinda out of the box for this challenge, so you may get dinged by the literal voters. I think you connected it well to the challenge, but I think the photo falls alittle short because the screen is too dim... Obviously this is a difficult shot to pull off, but the screen is just too difficult to see. 5', '2010-03-16 21:40:11.000000', NULL, 1),
(5907179, 860651, 93283, '<td valign="top">Nice movement in the water, branches lying around help connect it to the challenge, and I bumped this up upon third view from 5 to 6... good shot</td>', 'Nice movement in the water, branches lying around help connect it to the challenge, and I bumped this up upon third view from 5 to 6... good shot', '2010-03-16 21:41:35.000000', NULL, 1),
(5907186, 860349, 93283, '<td valign="top">What I like... this photo connects with the challenge nicely, exposure and contrast are good too... What I don''t like... The photo to me personally, isn''t that interesting. Obviously, that is a personal preference, but it just doesn''t do that much for me and for this challenge I''m trying to explain to everyone why I voted the way I did... 5</td>', 'What I like... this photo connects with the challenge nicely, exposure and contrast are good too... What I don''t like... The photo to me personally, isn''t that interesting. Obviously, that is a personal preference, but it just doesn''t do that much for me and for this challenge I''m trying to explain to everyone why I voted the way I did... 5', '2010-03-16 21:44:46.000000', NULL, 1),
(5907187, 860462, 93283, '<td valign="top">What I like about this shot is the composition, its unique in that perspective and connects to the challenge well. Where I think the image falls alittle short is that its a tad dark... In being too dark, it loses contrast in the sky. 5</td>', 'What I like about this shot is the composition, its unique in that perspective and connects to the challenge well. Where I think the image falls alittle short is that its a tad dark... In being too dark, it loses contrast in the sky. 5', '2010-03-16 21:46:09.000000', NULL, 1),
(5907188, 860683, 93283, '<td valign="top">The white branch on blue is definitely interesting. I like the contrast between subject and background and I''m bumping from 5 to 6 upon third view...</td>', 'The white branch on blue is definitely interesting. I like the contrast between subject and background and I''m bumping from 5 to 6 upon third view...', '2010-03-16 21:47:16.000000', NULL, 1),
(5907240, 860792, 49359, '<td valign="top">Absolutely beautiful :)</td>', 'Absolutely beautiful :)', '2010-03-16 22:35:30.000000', NULL, 1),
(5907640, 860604, 46918, '<td valign="top">Excellent shot...I love the angle and the lighting</td>', 'Excellent shot...I love the angle and the lighting', '2010-03-17 02:03:20.000000', NULL, 1),
(5907657, 860790, 46918, '<td valign="top">I''m not really big into blur shots</td>', 'I''m not really big into blur shots', '2010-03-17 02:15:21.000000', NULL, 1),
(5907659, 860645, 46918, '<td valign="top">Nice shot!!! Very difficult</td>', 'Nice shot!!! Very difficult', '2010-03-17 02:16:29.000000', NULL, 1),
(5907661, 860749, 46918, '<td valign="top">Nice shot...I think the border is a little too thick.</td>', 'Nice shot...I think the border is a little too thick.', '2010-03-17 02:18:44.000000', NULL, 1),
(5907664, 860529, 32011, '<td valign="top">A wonderful, wonderful image, which I''d have given a 10 if not for the slight haloing.  Also, not sure about the title, but will give you the benefit of the doubt and hope there''s an explanation in the description which I''ll check for once voting is complete.<br/> <br/>I love the processing on this... brilliant... (apart from the halos that is).  Simple composition really works for me, and the detail in the tree allows me to dwell on the image.  Bravo.</td>', 'A wonderful, wonderful image, which I''d have given a 10 if not for the slight haloing.  Also, not sure about the title, but will give you the benefit of the doubt and hope there''s an explanation in the description which I''ll check for once voting is complete. I love the processing on this... brilliant... (apart from the halos that is).  Simple composition really works for me, and the detail in the tree allows me to dwell on the image.  Bravo.', '2010-03-17 02:23:15.000000', NULL, 1),
(5907668, 860690, 32011, '<td valign="top">This is a wonderful work of art.  Great use of leading lines... simple, yet very effective... definitely not boring (a risk with "simple").  I love it, but I fear the voting masses might miss the beauty... if so I''ll be back to give this a MUAIMHO.</td>', 'This is a wonderful work of art.  Great use of leading lines... simple, yet very effective... definitely not boring (a risk with "simple").  I love it, but I fear the voting masses might miss the beauty... if so I''ll be back to give this a MUAIMHO.', '2010-03-17 02:25:40.000000', NULL, 1),
(5907670, 860605, 32011, '<td valign="top">WOW.  Best use of DOF in the challenge... easily.  Also, great colours and composition.</td>', 'WOW.  Best use of DOF in the challenge... easily.  Also, great colours and composition.', '2010-03-17 02:26:28.000000', NULL, 1),
(5907671, 860288, 32011, '<td valign="top">The drop on the spider web makes this image.  Ho-hum, DPC cliché without it... but with it, it''s excellent.</td>', 'The drop on the spider web makes this image.  Ho-hum, DPC cliché without it... but with it, it''s excellent.', '2010-03-17 02:27:33.000000', NULL, 1),
(5907674, 860783, 32011, '<td valign="top">I don''t understand this image''s relevance to the theme... but I love it none-the-less, and I''m going to assume there''s a "branch" connection and ignore my ignorance.  This is a great photo... wonderfully composed... makes me think, and I like that... but, I think too many voters will, like me wonder what the connection to the theme is, but unlike me, they masses will vote as if it''s a DNMC.  Some consolation if they do... I''ll be giving this a MUAIMHO... that is IF the voters don''t give this the love it deserves.</td>', 'I don''t understand this image''s relevance to the theme... but I love it none-the-less, and I''m going to assume there''s a "branch" connection and ignore my ignorance.  This is a great photo... wonderfully composed... makes me think, and I like that... but, I think too many voters will, like me wonder what the connection to the theme is, but unlike me, they masses will vote as if it''s a DNMC.  Some consolation if they do... I''ll be giving this a MUAIMHO... that is IF the voters don''t give this the love it deserves.', '2010-03-17 02:32:13.000000', NULL, 1),
(5907678, 859810, 32011, '<td valign="top">Great image, and one of the handful I''ve awarded my highest vote too in this challenge.  Love the warmth of the processing, and I''m a huge fan of the vignette.  The LOUD wallpaper is a nice touch, linking the antlers to the environment in which they would have once been... though with a creature attached to them one assumes.  One criticism of this, the border... I hate it when people knock me for my borders, and I hate doing it to others, but in this instance, the border here doesn''t work for me... or the image IMHO.</td>', 'Great image, and one of the handful I''ve awarded my highest vote too in this challenge.  Love the warmth of the processing, and I''m a huge fan of the vignette.  The LOUD wallpaper is a nice touch, linking the antlers to the environment in which they would have once been... though with a creature attached to them one assumes.  One criticism of this, the border... I hate it when people knock me for my borders, and I hate doing it to others, but in this instance, the border here doesn''t work for me... or the image IMHO.', '2010-03-17 02:36:14.000000', NULL, 1),
(5907736, 860702, 46918, '<td valign="top">LOL....I''m the big Daddy!!!! Anyway, great leading lines and great subject. I am a sucker for railroad type pics.</td>', 'LOL....I''m the big Daddy!!!! Anyway, great leading lines and great subject. I am a sucker for railroad type pics.', '2010-03-17 04:48:16.000000', NULL, 1),
