INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5912278, 860773, 63812, '<td valign="top">excellent</td>', 'excellent', '2010-03-21 22:49:14.000000', NULL, 1),
(5912280, 860282, 65234, '<td valign="top">Clever idea.</td>', 'Clever idea.', '2010-03-21 22:50:00.000000', NULL, 1),
(5912282, 860136, 67697, '<td valign="top">Amazing clarity.  What great timing!</td>', 'Amazing clarity.  What great timing!', '2010-03-21 22:52:07.000000', NULL, 1),
(5912283, 860399, 65234, '<td valign="top">Different but lots of fun to explore visually.  Almost looks like some kind of weird sea creature.</td>', 'Different but lots of fun to explore visually.  Almost looks like some kind of weird sea creature.', '2010-03-21 22:52:28.000000', NULL, 1),
(5912284, 860645, 67697, '<td valign="top">These colors do go so well together.  Great capture.</td>', 'These colors do go so well together.  Great capture.', '2010-03-21 22:52:39.000000', NULL, 1),
(5912286, 860528, 67697, '<td valign="top">I like the simplicity and the composition.</td>', 'I like the simplicity and the composition.', '2010-03-21 22:53:12.000000', NULL, 1),
(5912287, 860208, 67697, '<td valign="top">Very dramatic.  Looks like a movie still.  I''m waiting for the next scene where some wild animals will roam across the field.</td>', 'Very dramatic.  Looks like a movie still.  I''m waiting for the next scene where some wild animals will roam across the field.', '2010-03-21 22:53:54.000000', NULL, 1),
(5912289, 860209, 65234, '<td valign="top">Pretty family :-)  The expressions are great!</td>', 'Pretty family :-)  The expressions are great!', '2010-03-21 22:54:15.000000', NULL, 1),
(5912290, 860577, 67697, '<td valign="top">Beautiful and dramatic.  Love the colortone.</td>', 'Beautiful and dramatic.  Love the colortone.', '2010-03-21 22:54:40.000000', NULL, 1),
(5912292, 860652, 67697, '<td valign="top">Interesting object.  Love the framing.</td>', 'Interesting object.  Love the framing.', '2010-03-21 22:55:06.000000', NULL, 1),
(5912294, 860793, 65234, '<td valign="top">My yard is full of those suckers!  The poor dogs get them stuck in their pads all the time.  I like how you''ve captured this one; it looks quite ornamental.</td>', 'My yard is full of those suckers!  The poor dogs get them stuck in their pads all the time.  I like how you''ve captured this one; it looks quite ornamental.', '2010-03-21 22:55:39.000000', NULL, 1),
(5912296, 860379, 67697, '<td valign="top">Very pretty.  Love the bokeh.  The white vignette works so well here.</td>', 'Very pretty.  Love the bokeh.  The white vignette works so well here.', '2010-03-21 22:55:41.000000', NULL, 1),
(5912297, 860489, 67697, '<td valign="top">Love the vibrant colors.  What a great environmental portrait.</td>', 'Love the vibrant colors.  What a great environmental portrait.', '2010-03-21 22:56:15.000000', NULL, 1),
(5912298, 860816, 65234, '<td valign="top">I immediately went looking for the head on the exuberant dancing figure!</td>', 'I immediately went looking for the head on the exuberant dancing figure!', '2010-03-21 22:57:03.000000', NULL, 1),
(5912299, 859380, 110876, '<td valign="top">"A tree branch, a bank branch, a metaphorical branch. This word has many different meanings. Take a photograph relating to one of them."<br/> <br/>I tried, but I don''t get it.</td>', '"A tree branch, a bank branch, a metaphorical branch. This word has many different meanings. Take a photograph relating to one of them." I tried, but I don''t get it.', '2010-03-21 22:57:13.000000', NULL, 1),
(5912301, 860780, 67697, '<td valign="top">Beautiful bokeh.  Love the clarity on the pod.</td>', 'Beautiful bokeh.  Love the clarity on the pod.', '2010-03-21 22:58:36.000000', NULL, 1),
(5912305, 860773, 67697, '<td valign="top">Freaky and cool at the same time.  I almost expect to see a twister and a goth Dorothy to go with the crazy Toto you got here :)</td>', 'Freaky and cool at the same time.  I almost expect to see a twister and a goth Dorothy to go with the crazy Toto you got here :)', '2010-03-21 23:00:11.000000', NULL, 1),
(5912307, 860658, 65234, '<td valign="top">Wow'' somebody is certainly a talented wood carver.</td>', 'Wow'' somebody is certainly a talented wood carver.', '2010-03-21 23:01:21.000000', NULL, 1),
(5912309, 860722, 67697, '<td valign="top">This doesn''t say "branch" to me as much as some other photos do but just had to say that you did an awesome job with catching those crystals!</td>', 'This doesn''t say "branch" to me as much as some other photos do but just had to say that you did an awesome job with catching those crystals!', '2010-03-21 23:01:53.000000', NULL, 1),
(5912310, 860175, 65234, '<td valign="top">Like the concept and composition.  Looks a little washed out on my monitor.</td>', 'Like the concept and composition.  Looks a little washed out on my monitor.', '2010-03-21 23:02:07.000000', NULL, 1),
(5912316, 859739, 65234, '<td valign="top">Like the idea and that you kept the reflection in the shot (I think turtles basking on logs like this are really cute).  I would have used a bit more DOF to get the top of the turtles in focus.  Also it''s a bit overexposed looking on my screen.</td>', 'Like the idea and that you kept the reflection in the shot (I think turtles basking on logs like this are really cute).  I would have used a bit more DOF to get the top of the turtles in focus.  Also it''s a bit overexposed looking on my screen.', '2010-03-21 23:06:31.000000', NULL, 1),
(5912318, 860804, 65234, '<td valign="top">Well, now, that''s original!</td>', 'Well, now, that''s original!', '2010-03-21 23:07:28.000000', NULL, 1),
(5912320, 860773, 65234, '<td valign="top">What a cool shot!</td>', 'What a cool shot!', '2010-03-21 23:08:20.000000', NULL, 1),
(5912325, 860386, 65234, '<td valign="top">Interesting twisty branch and nice Night Heron perched on it.  On my screen the whole thing looks like it might need a white balance adjustment.</td>', 'Interesting twisty branch and nice Night Heron perched on it.  On my screen the whole thing looks like it might need a white balance adjustment.', '2010-03-21 23:11:04.000000', NULL, 1),
(5912327, 860511, 65234, '<td valign="top">Like the shadow and the dark sort of mood I feel in this.</td>', 'Like the shadow and the dark sort of mood I feel in this.', '2010-03-21 23:11:39.000000', NULL, 1),
(5912328, 860798, 65234, '<td valign="top">Nice job on the exposure; that sunburst is very pretty and there''s still lots of detail on the tree and branches.</td>', 'Nice job on the exposure; that sunburst is very pretty and there''s still lots of detail on the tree and branches.', '2010-03-21 23:12:23.000000', NULL, 1),
(5912329, 860605, 65234, '<td valign="top">Love the shallow DOF :-)  I could get lost exploring this one.</td>', 'Love the shallow DOF :-)  I could get lost exploring this one.', '2010-03-21 23:12:29.000000', NULL, 1),
(5912330, 860525, 65234, '<td valign="top">Nice depiction of early spring weather.</td>', 'Nice depiction of early spring weather.', '2010-03-21 23:12:32.000000', NULL, 1),
(5912331, 860426, 65234, '<td valign="top">Well and thoroughly framed.</td>', 'Well and thoroughly framed.', '2010-03-21 23:12:34.000000', NULL, 1),
(5912332, 860780, 65234, '<td valign="top">Pretty colors and composition; really like the shapes in the bokeh.</td>', 'Pretty colors and composition; really like the shapes in the bokeh.', '2010-03-21 23:12:37.000000', NULL, 1),
